#include "esp_camera.h"
#include "soc/soc.h"
#include "soc/rtc_cntl_reg.h"

// Определение пинов согласно вашей схеме подключения
#define CAMERA_PIN_PWDN    -1  // Если PWDN не подключен, оставляем -1
#define CAMERA_PIN_RESET   -1  // Если RESET не подключен, оставляем -1
#define CAMERA_PIN_XCLK    18  // xlk - d18
#define CAMERA_PIN_SIOD    4   // sda - d4
#define CAMERA_PIN_SIOC    12  // scl - d12

// Пины шины данных (D7 - D0)
#define CAMERA_PIN_D7      32  // d7 - d32
#define CAMERA_PIN_D6      27  // d6 - d27
#define CAMERA_PIN_D5      35  // d5 - d35
#define CAMERA_PIN_D4      23  // d4 - d23
#define CAMERA_PIN_D3      26  // d3 - d26
#define CAMERA_PIN_D2      33  // d2 - d33
#define CAMERA_PIN_D1      25  // d1 - d25
#define CAMERA_PIN_D0      34  // d0 - d34

// Сигналы синхронизации
#define CAMERA_PIN_VSYNC   19  // vs - d19
#define CAMERA_PIN_HREF    -1  // В вашей схеме нет HREF. Для OV7670 без FIFO он обычно нужен. Подставьте пин, если забыли указать.
#define CAMERA_PIN_PCLK    21  // plk - d21

void setup() {
  // Отключаем brownout detector (защиту от просадки напряжения)
  WRITE_PERI_REG(RTC_CNTL_BROWN_OUT_REG, 0); 

  Serial.begin(115200);
  Serial.setDebugOutput(true);
  Serial.println();

  camera_config_t config;
  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer = LEDC_TIMER_0;
  config.pin_d0 = CAMERA_PIN_D0;
  config.pin_d1 = CAMERA_PIN_D1;
  config.pin_d2 = CAMERA_PIN_D2;
  config.pin_d3 = CAMERA_PIN_D3;
  config.pin_d4 = CAMERA_PIN_D4;
  config.pin_d5 = CAMERA_PIN_D5;
  config.pin_d6 = CAMERA_PIN_D6;
  config.pin_d7 = CAMERA_PIN_D7;
  config.pin_xclk = CAMERA_PIN_XCLK;
  config.pin_pclk = CAMERA_PIN_PCLK;
  config.pin_vsync = CAMERA_PIN_VSYNC;
  config.pin_href = CAMERA_PIN_HREF;
  config.pin_sccb_sda = CAMERA_PIN_SIOD;
  config.pin_sccb_scl = CAMERA_PIN_SIOC;
  config.pin_pwdn = CAMERA_PIN_PWDN;
  config.pin_reset = CAMERA_PIN_RESET;

  // Частота XCLK для OV7670 (обычно 10MHz - 20MHz)
  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_JPEG; // Использовать PIXFORMAT_YUV422 или RGB565, если JPEG не поддерживается прошивкой камеры

  // Настройки формата кадра (для OV7670 без FIFO лучше начинать с небольших разрешений, например QVGA)
  config.frame_size = FRAMESIZE_QVGA; 
  config.jpeg_quality = 12;
  config.fb_count = 1;

  // Инициализация камеры
  esp_err_t err = esp_camera_init(&config);
  if (err != ESP_OK) {
    Serial.printf("Ошибка инициализации камеры: 0x%x", err);
    return;
  }

  Serial.println("Камера успешно настроена и готова к работе!");
}

void loop() {
  // Захват кадра
  camera_fb_t * fb = esp_camera_fb_get();
  if (!fb) {
    Serial.println("Не удалось захватить кадр");
    delay(1000);
    return;
  }

  // Здесь можно что-то сделать с кадром (fb->buf - указатель на данные, fb->len - размер)
  Serial.printf("Кадр захвачен. Размер: %u байт\n", fb->len);

  // Обязательно освобождаем буфер памяти обратно для DMA
  esp_camera_fb_return(fb);

  delay(5000); // Пауза 5 секунд между кадрами
}
